import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易集註 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易集註 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"classics/jizhu/005.md","filePath":"classics/jizhu/005.md"}'),l={name:"classics/jizhu/005.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>乾，卦名。元亨利貞者，文王所繫之辭，以斷一卦之吉凶，所謂彖辭也。乾者健也，陽主於動，動而有常，其動不息，非至健不能。奇者陽之數，天者陽之體，健者陽之性，如火性熱水性寒也。六畫皆奇，則純陽而至健矣，故不言天而言幹也。元大，亨通，利宜，貞正而固也。元亨者，天道之本然，數也。利貞者，人事之當然，理也。易經理數不相離，因乾道陽明純粹，無纖毫陰柔之私，惟天與聖人足以當之，所以斷其必大亨也。故數當大亨而必以貞處之，方與乾道相合。若其不貞，少有人慾之私，則人事之當然者廢，又安能元亨乎。故文王言，筮得此卦者大亨而宜於正固，此則聖人作易，開物成務，冒天下之道，教人以反身修省之切要也。學者能於此四字潛心焉，傳心之要不外是矣。此文王占卜所繫之辭，不可即指為四德。至孔子文言，純以義理論，方指為四德也。蓋占卜，不論天子，不論庶人，皆宜於貞，若即以為四德，失文王立教之意矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><h3 id="大哉乾元-萬物資始-乃統天。" tabindex="-1">大哉乾元，萬物資始，乃統天。 <a class="header-anchor" href="#大哉乾元-萬物資始-乃統天。" aria-label="Permalink to “大哉乾元，萬物資始，乃統天。”">​</a></h3><p>乾元亨利貞者，文王所繫之辭，彖之經也。此則孔子贊經之辭，彖之傳也。故亦以彖曰起之。彖者材也，言一卦之材也。後人解彖者斷也，又解豕走悅，又解為茅犀之名，不如只依孔子材之一字可也。下文象曰象字亦然。易本占卜之書，曰元亨利貞者，文王主於卜筮以教人。至於孔子之傳，則專於義理矣，故以元亨利貞，分為四德，此則專以天道發明幹義也。大哉，嘆辭。乾元者，幹之元也。元者大也，始也。始者，物之始，非以萬物之始即元也。言萬物所資以始者，此乃四德之元也。此言氣而不言形，若涉於形，便是坤之資生矣。統，包括也，乾元乃天德之大始，故萬物之生，皆資之以為始。又為四德之首，而貫乎天德之始終，故統天。天之為天，出乎震，而生長收藏，不過此四德而己，統四德則統天矣。資始者，無物不有也。統天者，無時不然也。無物不有，無時不然，此乾元之所以為大也。此釋元之義。</p><h3 id="雲行雨施-品物流形。" tabindex="-1">雲行雨施，品物流形。 <a class="header-anchor" href="#雲行雨施-品物流形。" aria-label="Permalink to “雲行雨施，品物流形。”">​</a></h3><p>有是氣即有是形。資始者氣也，氣發洩之盛，則雲行雨施矣。品者，物各分類。流者，物各以類而生生不已，其機不停滯也。雲行雨施者氣之亨，品物流形者物隨造化以亨也。雖物之亨通，而其實乾德之亨通也。此釋幹之亨。施有二義，平聲者用也加也設也，去聲者布也散也惠也與也。此則去聲之義。</p><h3 id="大明終始-六位時成-時乘六龍以御天。" tabindex="-1">大明終始，六位時成，時乘六龍以御天。 <a class="header-anchor" href="#大明終始-六位時成-時乘六龍以御天。" aria-label="Permalink to “大明終始，六位時成，時乘六龍以御天。”">​</a></h3><p>大明者，默契也。終謂上爻，始謂初爻。即初辭擬之，卒成之終，原始要終以為質也。觀下句六位二字可見矣。六位者六爻也，時者六爻相雜，惟其時物之時也。爻有定位，故曰六位。六龍者，潛與亢之六龍六陽也。陽有變化，故曰六龍。乘者憑據也，御者御車之御，猶運用也。上文言統者，統治綱領，統天之統如身之統四體。此節言御者，分治條目。御天之御，如心之御五官。六位時成者，如位在初時當為潛，位在上時當為亢也。御天者，行天道也。當處之時則乘潛龍，當出之時則乘飛龍，時當勿用聖人則勿用，時當知悔聖人則知悔也。乘龍御天，只是時中。乘六龍便是御天，謂之曰乘龍御天，則是聖人一身常駕馭乎幹之六龍，而幹之六龍常在聖人運用之中矣。學者當觀其時成時乘，聖人時中變化，行無轍跡之妙可也。然言天道而配以聖人何也?蓋天下之理得而成位乎中，則參天地者惟聖人也，故頤卦曰聖人養賢以及萬民，鹹卦曰聖人感人心而天下和平，恆卦曰聖人久於其道而天下化成，皆此意。</p><p>言聖人默契乾道六爻終始之理，見六爻之位各有攸當，皆以時自然而成，則六陽淺深進退之時，皆在吾運用之中矣。由是時乘六龍，以行天道，則聖即天也。上一節專贊乾元，此一節則贊聖人，知幹六爻之理而行乾元之事。則澤及於物，足以為萬國咸寧之基本矣，乃聖人之元亨也。</p><h3 id="乾道變化-各正性命-保合太和-乃利貞。" tabindex="-1">乾道變化，各正性命，保合太和，乃利貞。 <a class="header-anchor" href="#乾道變化-各正性命-保合太和-乃利貞。" aria-label="Permalink to “乾道變化，各正性命，保合太和，乃利貞。”">​</a></h3><p>變者化之漸，化者變之成。各者各自也，即一物原來有一身，各有族類，不混淆也。正者不偏也，言萬物受質，各得其宜，即一身還有一乾坤，不得倚附妨害也。物所受為性，天所賦為命，保者常存而不虧，合者翕聚而不散。太和，陰陽會合，沖和之氣也。各正者，各正於萬物向實之初。保合者，保合於萬物向實之後。就各正言，則曰性命，性命雖以理言而不離乎氣。就保合言，則曰太和，雖以氣言，而不離乎理，其實非有二也。</p><p>言乾道變化不窮，固品物流形矣。至秋則物皆向實，各正其所受所賦之性命，至冬則保全其太和生意，隨在飽足，無少缺欠。凡資始於元，流形於亨者，至此告其終，斂其跡矣，雖萬物之利貞，實乾道之利貞也，故曰乃利貞。</p><h3 id="首出庶物-萬國咸寧。" tabindex="-1">首出庶物，萬國咸寧。 <a class="header-anchor" href="#首出庶物-萬國咸寧。" aria-label="Permalink to “首出庶物，萬國咸寧。”">​</a></h3><p>乘龍御天，乃聖人王道之始，為天下開太平，至此則惟端拱首出於萬民之上。如乾道變化，無所作為，而萬國咸寧，亦如物之各正保合也。乘龍御天之化至此，成其功矣，此則聖人之利貞也。咸寧之寧，即各正保合也，其文武成康之時乎，漢文帝亦近之。如不能各正保合，則紛紜煩擾矣，豈得寧。</p><p>《象》曰：天行健，君子以自彊不息。</p><p>象者，伏羲卦之上下兩象，周公六爻所繫辭之象也，即彖辭之下，即以彖曰起之是也。天行者，天之運行，一日一週也。健者運而不息也，其不息者，以陽之性至健，所以不息也。以者用也，有所因而用之，之辭即箕子以之之以也。體易而用之，乃孔子示萬世學者用易之方也。自彊者，一念一事，莫非天德之剛也。息者，間以人慾也。天理周流，人慾退聽，故自彊不息，若少有一毫陰柔之私以間之，則息矣。彊與息反，如公與私反。自彊不息，猶雲至公無私。天行健者，在天之幹也。自彊不息者，在我之幹也。上句以卦言，下句以人事言，諸卦仿此。</p><p>初九，潛龍勿用。</p><p>此周公所繫之辭，以斷一爻之吉凶，所謂爻辭也。凡畫卦者，自下而上，故謂下爻為初。初九者，卦下陽爻之名也。陽曰九，陰曰六者，河圖洛書，五皆居中，則五者數之祖也，故聖人起數，止於一二三四五。參天兩地而倚數，參天者，天之位三，天一天三天五也。兩地者，地之二位也，地二地四也。倚者依也，天一依天三，天三依天五而為九，所以陽皆言九。地二依地四而為六，所以陰皆言六。一二三四五者，生數也，六七八九十者，成數也。然生數者成之端倪，成數者生之結果，故止以生數起之。過揲之數，皆以此九六之參兩，所以爻言九六也。潛藏也，象初。龍陽物，變化莫測，亦猶乾道變化，故象九。且此爻變巽錯震，亦有龍象，故六爻即以龍言之，所謂擬諸形容象其物宜者此也。勿用者，未可施用也。象為潛龍，佔為勿用，故佔得幹而遇此爻之變者，當觀此象，而玩此佔也。諸爻仿此。易不似別經，不可為典要，如佔得潛龍之象，在天子則當傳位，在公卿則當退休，在士子則當靜修，在賢人則當隱逸，在商賈則當待價，在戰陣則當左次，在女子則當愆期，萬事萬物莫不皆然。若不知象，一爻止一事，則三百八十四爻止作得三百八十四件事矣。何以彌綸天地?此訓象訓字訓錯綜之義，圈外方是正意。三百八十四爻仿此。</p><p>初九陽氣方萌，在於卦下，蓋龍之潛藏而未出者也，故有潛龍之象。龍未出潛，則未可施用矣，故教佔者勿用，養晦以俟時可也。</p><h3 id="象曰-潛龍勿用-陽在下也。" tabindex="-1">象曰：潛龍勿用，陽在下也。 <a class="header-anchor" href="#象曰-潛龍勿用-陽在下也。" aria-label="Permalink to “象曰：潛龍勿用，陽在下也。”">​</a></h3><p>陽在下者，陽爻居於下也。陽故稱龍，在下，故勿用。此以下舉周公所繫六爻之辭而釋之，幹初曰陽在下，坤初曰陰始凝，扶陽抑陰之意見矣。</p><p>九二，見龍在田，利見大人。</p><p>二謂自下而上第二爻也。九二非正，然剛健中正，本幹之德，故舊注亦以正言之。見者，初為潛，二則離潛而出見也。田者，地之有水者也，以六畫卦言之，二於三才為地道，地上即田也。大人者，大德之人也，陽大陰小，乾卦六爻皆陽，故為大，以三畫卦言之，二於三才為人道，大人之象也。故稱大人，所以應爻九五亦曰大人。二五得稱大人者，皆以三畫卦言也。利見大人者，利見九五之君，以行其道也。如仕進則利見君，如雜佔則即今占卜利見貴人之類。此爻變離，有同人象，故利見大人。</p><p>九二以陽剛中正之德，當出潛離隱之時，而上應九五之君，故有此象，而其佔則利見大人也。佔者有是德，方應是佔矣。</p><h3 id="象曰-見龍在田-德施普也。" tabindex="-1">象曰：見龍在田，德施普也。 <a class="header-anchor" href="#象曰-見龍在田-德施普也。" aria-label="Permalink to “象曰：見龍在田，德施普也。”">​</a></h3><p>德，即剛健中正之德。出潛離隱，則君德已著，周遍於物，故曰德施普。施字如程傳作去聲。</p><p>九三，君子終日乾乾，夕惕若，厲，無咎。</p><p>君子指佔者，以六畫卦言之，三於三才為人道，以乾德而居人道，君子之象也，故三不言龍。三變則中爻為離，離日在下卦之中，終日之象也。下幹終而上幹繼，乾乾之象，乃健而不息也。終日是晝，夕則將夜，惕憂也。變離錯坎，憂之象也。若，助語辭。夕對終日言。終日乾乾夕惕若者，言終日乾乾，雖至於夕，而兢惕之心，猶夫終日也。厲者，危厲不安也。九陽爻，三陽位，過則不中，多兇之地也，故言厲。無咎者，以危道處危地，操心危慮患深，則終於不危矣，此不易之理也，故無咎。</p><p>九三過剛不中，若有咎矣。然性體剛健，有能朝夕兢惕不已之象，佔者能憂懼如是，亦無咎也。</p><h3 id="象曰-終日乾乾-反覆道也。" tabindex="-1">象曰：終日乾乾，反覆道也。 <a class="header-anchor" href="#象曰-終日乾乾-反覆道也。" aria-label="Permalink to “象曰：終日乾乾，反覆道也。”">​</a></h3><p>反覆猶往來，言君子之所以幹夕兢惕，汲汲皇皇，往來而不已者，無非此道而已。動循天理，所以處危地而無咎。道外無德，故二爻言德。</p><p>九四，或躍在淵，無咎。</p><p>或者欲進未定之辭，非猶豫狐疑也。或躍在淵者，欲躍猶在淵也。九為陽，陽動故言躍。四為陰，陰虛故象淵。此爻變巽為進退，為不果。又四多懼，故或躍在淵。</p><p>九四以陽居陰，陽則志於進，陰則不果於進，居上之下，當改革之際，欲進未定之時也，故有或躍在淵之象。佔者能隨時進退，斯無咎矣。</p><h3 id="象曰-或躍在淵-進無咎也。" tabindex="-1">象曰：或躍在淵，進無咎也。 <a class="header-anchor" href="#象曰-或躍在淵-進無咎也。" aria-label="Permalink to “象曰：或躍在淵，進無咎也。”">​</a></h3><p>量可而進，適其時則無咎，故孔子加一進字以斷之。</p><p>九五，飛龍在天，利見大人。</p><p>五，天位，龍飛於天之象也。佔法與九二同者，二五皆中位，特分上下耳。利見大人，如堯之見舜，高宗之見傅說是也。下此如沛公之見張良，昭烈之見孔明，亦庶幾近之。六畫之卦，五為天，三畫之卦，五為人，故曰天曰人。</p><p>九五剛健中正，以聖人之德，居天子之位，而下應九二，故其象佔如此。佔者如無九五之德位，必不應利見之佔矣。</p><h3 id="象曰-飛龍在天-大人造也。" tabindex="-1">象曰：飛龍在天，大人造也。 <a class="header-anchor" href="#象曰-飛龍在天-大人造也。" aria-label="Permalink to “象曰：飛龍在天，大人造也。”">​</a></h3><p>造作也，言作而在上也，非製作之作。大人龍也，飛在天，作而在上也。大人，釋龍字。造釋飛字。此止言飛龍在天。下同聲相應一節，則言利見大人。上治一節，方言大人之事。乃位乎天德一節，則見其非無德而據尊位，四意自別。</p><p>上九，亢龍有悔。</p><p>上者，最上一爻之名。亢，以戶唐切，人頸也，以苦浪切，高也。吳幼清以人之喉骨剛而居高是也。蓋上而不能下，信而不能屈之意。陰陽之理，極處必變，陽極則生陰，陰極則生陽，消長盈虛，此一定之理數也。龍之為物，始而潛，繼而見，中而躍，終而飛，既飛於天，至秋分又蟄而潛於淵，此知進知退，變化莫測之物也。九五飛龍在天位之極，中正者，得時之極，乃在於此，若復過於此，則極而亢矣。以時則極，以勢則窮，安得不悔。</p><p>上九陽剛之極，有亢龍之象，故佔者有悔。知進知退，不與時偕極，斯無悔矣。伊尹之復政厥闢，周公之罔以寵利居成功，皆無悔者也。</p><h3 id="象曰-亢龍有悔-盈不可久也。" tabindex="-1">象曰：亢龍有悔，盈不可久也。 <a class="header-anchor" href="#象曰-亢龍有悔-盈不可久也。" aria-label="Permalink to “象曰：亢龍有悔，盈不可久也。”">​</a></h3><p>此陰陽盈虛一定之理，盈即亢，不可久，致悔之由。</p><p>用九，見群龍無首，吉。</p><p>此因上九亢龍有悔而言之。用九者，猶言處此上九之位也。上九貴而無位，高而無民，賢人在下位而無輔，動而有悔矣。到此何以處之哉?惟見群龍無首則吉。群龍者，潛見躍飛之龍也。首者頭也，幹為首。凡卦，初為足，上為首，則上九即群龍之首也。不見其首則陽變為陰，剛變為柔，知進知退，知存知亡，知得知喪，不為窮災，不與時偕極，乃見天則而天下治矣，所以無悔而吉。此聖人開遷善之門，教佔者用此道也。故陽極則教以見群龍無首吉，陰極則教以利永貞。蓋居九而為九所用，我不能用九，故至於亢。居六而為六所用，我不能用六，故至於戰。惟見群龍無首利永貞，此用九用六之道也。幹主知，坤主能，故言利永貞。用易存乎人，故聖人教之以此。昔王介甫常欲系用九於亢龍有悔之下，得其旨矣。</p><h3 id="象曰-用九-天德不可為首也。" tabindex="-1">象曰：用九，天德不可為首也。 <a class="header-anchor" href="#象曰-用九-天德不可為首也。" aria-label="Permalink to “象曰：用九，天德不可為首也。”">​</a></h3><p>天德二字，即乾道二字。首頭也，即見群龍無首之首也。言周公爻辭，用九見群龍無首吉者何也，以天德不可為首，而見其首也。蓋陽剛之極，亢則有悔，故用其九者，剛而能柔，有群龍無首之象則吉矣。天行以下，先儒謂之大象，潛龍以下，先儒謂之小象，後仿此。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><h3 id="元者善之長也-亨者嘉之會也-利者義之和也-貞者事之幹也。" tabindex="-1">元者善之長也，亨者嘉之會也，利者義之和也，貞者事之幹也。 <a class="header-anchor" href="#元者善之長也-亨者嘉之會也-利者義之和也-貞者事之幹也。" aria-label="Permalink to “元者善之長也，亨者嘉之會也，利者義之和也，貞者事之幹也。”">​</a></h3><p>孔子於彖象既作之後，猶以為未盡其蘊也，故又設文言以明之。文言者，依文以言其理，亦有文之言辭也。乾道所包者廣，有在天之元亨利貞，有聖人之元亨利貞，有在人所具之元亨利貞，此則就人所具而言也。元，大也，始也，即在人之仁也。仁義禮智皆善也，但仁則善端初發，義禮智皆所從出，故為善之長。亨者自理之顯著亨通而言，即在人之禮也。嘉，美之會聚也。利有二義，以人心言之，義為天理，利為人慾，此以利慾而言也。以天理言之，義者利之理和者，義之宜以合宜而言也，故利即吾性之義，義安處即利也。如上下彼此，各得其當然之分，不相乖戾，此利也，乃義之和也。貞有三意，知也正也固也，如孟子所謂知斯二者弗去是也。知者，知之意也;惟知事親從兄，正之意也;弗去，固之意也。故貞即吾性之智。幹者莖幹也，木之身也。其義意則能事也，如木之身而枝葉所依以立也。築牆兩旁木製板者為幹，從木，此字則從幹。元就其理之發端而言，亨就其理之聚會而言，利就其理之各歸分願而言，貞就其理之確實而言，名雖有四，其實一理而已，皆天下之至公，而無一毫人慾之私者也。此四句說天德之自然，下體仁四句，說人事之當然。</p><h3 id="君子體仁足以長人-嘉會足以合禮-利物足以和義-貞固足以幹事。" tabindex="-1">君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以幹事。 <a class="header-anchor" href="#君子體仁足以長人-嘉會足以合禮-利物足以和義-貞固足以幹事。" aria-label="Permalink to “君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以幹事。”">​</a></h3><p>體者，所存所發，無不在於仁也。能體其仁，則欲立欲達，無所往而莫非真愛，自足以長人矣。長者克君克長之長，蓋仁者宜在高位也，既足以長人，則善之長在我矣。下三句仿此。嘉會者，嘉美其會，聚於一身也。禮之方行，升降上下，進退屈伸，辭讓授受，往來酬酢，未有單行獨坐而可以行禮者，此之謂會。然其聚會，必至善恰好，皆天理人情自然之至，而無不嘉美焉，此之謂嘉。嘉美會聚於一身，則動容周旋，無不中禮，自有以合乎天理之節文，人事之儀則矣。蓋此理在日用間，隨處充足，無少欠缺。禮儀三百，威儀三千，無一事而非仁，若少有一毫欠缺，非美會矣，安能合禮。不相妨害之謂利，利則必和無所乖戾之謂和，和則必利，蓋義公天下之利，本有自然之和也。物者義之體，義者物之用，乃處物得宜之謂也。物雖萬有不齊，然各有自然之定理，故能處物得宜而不相妨害，則上下尊卑之間，自恩義洽浹，無所乖戾，而義無不合矣。固者，堅固不搖，乃貞之恆久正大也。蓋事有未正，必欲其正，事之既正，必守其正，此貞固二字之義也。貞而又固，故足以幹事。幹者事之幹也，賴之為依據也。亦猶木有幹而枝葉可依也。凡事或不能貞，或貞而不固，皆知不能及之，是以不能擇而守之，故非至靈至明，是非確然不可移易者，決不能貞固，所以貞固為智之事。</p><h3 id="君子行此四德者-故曰乾元亨利貞。" tabindex="-1">君子行此四德者，故曰乾元亨利貞。 <a class="header-anchor" href="#君子行此四德者-故曰乾元亨利貞。" aria-label="Permalink to “君子行此四德者，故曰乾元亨利貞。”">​</a></h3><p>故曰，古語也。行此四德，即體仁嘉會利物貞固也。行此四德，則與乾元合其德矣，故曰乾元亨利貞，所以明君子即幹也。</p><h3 id="初九曰-潛龍勿用-何謂也-子曰-龍-德而隱者也-不易乎世-不成乎名-遁世無悶-不見是而無悶-樂則行之-憂則違之-確乎其不可拔-潛龍也。" tabindex="-1">初九曰“潛龍勿用”，何謂也?子曰：龍，德而隱者也，不易乎世，不成乎名，遁世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。 <a class="header-anchor" href="#初九曰-潛龍勿用-何謂也-子曰-龍-德而隱者也-不易乎世-不成乎名-遁世無悶-不見是而無悶-樂則行之-憂則違之-確乎其不可拔-潛龍也。" aria-label="Permalink to “初九曰“潛龍勿用”，何謂也?子曰：龍，德而隱者也，不易乎世，不成乎名，遁世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。”">​</a></h3><p>初九曰潛龍勿用何謂也，此文章問答之祖也。後儒如屈原《漁父》見而問之、揚雄《法言》用或問，皆祖於此。聖人神明不測，故曰龍德隱，在下位也。易移也，不易乎世者，邪世不能亂，不為世所移而能拔於流俗風靡之中也。不成乎名者，務實不務名，有一才一藝之長，不求知於世，以成就我之名也。遁世無悶者，不見用於世而不悶也。不見是而無悶者，不見信於人而不悶也。事有快樂於心者，則奮然而行之，忘食忘憂之類是也。事有拂逆於心者，則順適而背之，伐木絕糧之類是也。違者背也，言不以拂逆為事，皆置之度外而背之背後不見之意。如困於陳蔡，猶援琴而歌是也，蓋不易乎世，而不為世所用，不成乎名，而不為世所取，則必遁世而不見信於人矣，而聖人皆無悶焉。是以日用之間，莫非此道之遊衍。凡一切禍福譭譽，如太虛浮雲，皆處之泰然，無意必固我之私，此所以樂則行，憂則違，憂樂皆無與於己，而安於所遇矣，非龍德何以有此?拔者擢也，舉而用之也。不可拔，即勿用也，言堅確不可舉用也。蓋不易乎世六句，龍德也，確乎其不可拔而隱也。龍德而隱，此所以為潛龍也。乾卦六爻，文言皆以聖人明之，有隱顯，無淺深。</p><h3 id="九二曰-見龍在田-利見大人-何謂也-子曰-龍德而正中者也-庸言之信-庸行之謹-閒邪存其誠-善世而不伐-德博而化。易曰-見龍在田-利見大人-君德也。" tabindex="-1">九二曰“見龍在田，利見大人”，何謂也?子曰：龍德而正中者也，庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化。易曰“見龍在田，利見大人”，君德也。 <a class="header-anchor" href="#九二曰-見龍在田-利見大人-何謂也-子曰-龍德而正中者也-庸言之信-庸行之謹-閒邪存其誠-善世而不伐-德博而化。易曰-見龍在田-利見大人-君德也。" aria-label="Permalink to “九二曰“見龍在田，利見大人”，何謂也?子曰：龍德而正中者也，庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化。易曰“見龍在田，利見大人”，君德也。”">​</a></h3><p>正中者，以下卦言初居下，三居上，二正當其中也。庸常也。邪自外入，故防閒之。誠自我有，故存主之。庸言必信者，無一言之不信也。庸行必謹者，無一行之不謹也。庸言庸行，亦信亦謹，宜無事於閒邪矣，而猶閒邪存誠。閒邪存其誠者，無一念之不誠也，念念皆誠，則發之言行愈信謹矣。如此則其德已盛，善蓋一世矣。然心不自滿，不自以為善，其主謹閒邪存誠猶夫其初也，皆純一不已之功也。德博而化者，言行為人所取法也。言君德者，明其非君位也。</p><h3 id="九三曰-君子終日乾乾-夕惕若-厲無咎-何謂也-子曰-君子進德修業-忠信所以進德也-修辭立其誠所以居業也。知至至之-可與幾也。知終終之-可與存義也。是故居上位而不驕-在下位而不憂-故乾乾因其時而惕-雖危無咎矣。" tabindex="-1">九三曰“君子終日乾乾，夕惕若，厲無咎”，何謂也?子曰：君子進德修業，忠信所以進德也，修辭立其誠所以居業也。知至至之，可與幾也。知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。 <a class="header-anchor" href="#九三曰-君子終日乾乾-夕惕若-厲無咎-何謂也-子曰-君子進德修業-忠信所以進德也-修辭立其誠所以居業也。知至至之-可與幾也。知終終之-可與存義也。是故居上位而不驕-在下位而不憂-故乾乾因其時而惕-雖危無咎矣。" aria-label="Permalink to “九三曰“君子終日乾乾，夕惕若，厲無咎”，何謂也?子曰：君子進德修業，忠信所以進德也，修辭立其誠所以居業也。知至至之，可與幾也。知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。”">​</a></h3><p>幾與義非二事。幾者心之初動也，當欲忠信修辭立誠之初，心之萌動，必有其幾。幾微之際，乃義之發源處也。義者事之得宜也，方忠信修辭立誠之後，事之成就必見乎義，允蹈之宜，乃幾之結果處也。與者許也，可與幾者，幾有善惡，許其幾之如此，方不差也。存者守而不失也。三爻變，則中爻為巽，有進象，又為兌，有言辭象，又為離明，有知象。以三畫卦論，三居上，居上位象。以六畫卦論，三居下，在下位象。</p><p>君子終日乾乾夕惕若者，非無事而徒動也，勤於進德修業也。然以何者為德業，德業何以用功?蓋德者，即貞實之理，誠之涵於心者也。人不忠信，則此心不實，安能進德，惟忠信而內無一念之不實，則心不外馳，而有以復還其貞實之理，所進之德，自日新而不窮矣。故所以進德業者，即貞實之事。誠之發於事者也，言不顧行，則事皆虛偽，安能居業?惟修省其辭以立誠，而外無一言之不實，則言行相顧有以允蹈其貞實之事，所居之業，自居安而不遷矣，故所以居業。夫德業之進修，固在於忠信修辭立誠矣。然其入門用功，當何如哉?亦知行並進而已。蓋其始也，知德業之所當至，此心必有其幾，當幾之初，下此實心，而必欲其至，知至即至之，則念念不差，意可得而誠矣。幾動不差，此其所以可與幾也。其終也，知德業之所當終，此事必有其義，見義之時，行此實事，而必欲其終，知終即終之，則事事皆當身可得而修矣。義守不失，此其所以可與存義也，如此用功，則反身而誠，德崇而業廣矣。又焉往而不宜哉!故以之居上，高而不驕。以之在下，卑而不戚，雖危無咎矣。此君子所以終日乾乾也。</p><h3 id="九四曰-或躍在淵-無咎-何謂也-子曰-上下無常-非為邪也-進退無恆-非離群也。君子進德修業-欲及時也-故無咎。" tabindex="-1">九四曰“或躍在淵，無咎”，何謂也?子曰：上下無常，非為邪也;進退無恆，非離群也。君子進德修業，欲及時也，故無咎。 <a class="header-anchor" href="#九四曰-或躍在淵-無咎-何謂也-子曰-上下無常-非為邪也-進退無恆-非離群也。君子進德修業-欲及時也-故無咎。" aria-label="Permalink to “九四曰“或躍在淵，無咎”，何謂也?子曰：上下無常，非為邪也;進退無恆，非離群也。君子進德修業，欲及時也，故無咎。”">​</a></h3><p>在田者，安於下，在天者，安於上，有常者也。進而為飛，退而為見，有恆者也。恆即常字，九四之位，逼九五矣，以上進為常，則覬覦而心邪。今或躍或處，上下無常，而非為邪也。以下退為常，則離群而德孤。今去就從宜，進退無常，而非離群也。惟及時以進修，而不幹時以行險，此其所以無咎也。上進釋躍字義，下退釋淵字義。無常無恆釋或字義。非為邪，非離群，釋無咎義。</p><h3 id="九五曰-飛龍在天-利見大人-何謂也-子曰-同聲相應-同氣相求。水流溼-火就燥。雲從龍-風從虎-聖人作而萬物睹。本乎天者親上-本乎地者親下-則各從其類也。" tabindex="-1">九五曰“飛龍在天，利見大人”，何謂也?子曰：同聲相應，同氣相求。水流溼，火就燥。雲從龍，風從虎，聖人作而萬物睹。本乎天者親上，本乎地者親下，則各從其類也。 <a class="header-anchor" href="#九五曰-飛龍在天-利見大人-何謂也-子曰-同聲相應-同氣相求。水流溼-火就燥。雲從龍-風從虎-聖人作而萬物睹。本乎天者親上-本乎地者親下-則各從其類也。" aria-label="Permalink to “九五曰“飛龍在天，利見大人”，何謂也?子曰：同聲相應，同氣相求。水流溼，火就燥。雲從龍，風從虎，聖人作而萬物睹。本乎天者親上，本乎地者親下，則各從其類也。”">​</a></h3><p>同聲相應，如鶴鳴而子和，雄鳴而雌應之類是也。同氣相求，如日火之精，而取火於日。月水之精，而取水於月之類是也。溼者下地，故水之流趨之。燥者幹物，故火之然就之。雲水氣也，龍興則雲生，故云從龍。風陰氣也，虎嘯則風烈，故風從虎。然此特一物親一物也。惟聖人以聖人之德，居天子之位，則三才之主，而萬物之天地矣。是以天下萬民莫不瞻仰其德，而快睹其光。所謂首出庶物，萬國咸寧，而萬物皆親矣。蓋不特一物之親而已也，所以然者，以天地陰陽之理，皆各從其類也。如天在上，輕清者也，凡本乎天，日月星辰，輕清成象者，皆親之。地在下，重濁者也，凡本乎地，蟲獸草木，重濁成形者，皆親之。蓋天屬陽，輕清者屬陽，故從其陽之類;地屬陰，重濁者屬陰，故從其陰之類。陽從其陽，故君子與君子同類而相親，陰從其陰，故小人與小人同類而相親。然則以九五之德位，豈不利見同類之大人，所以利見者以此。</p><h3 id="上九曰-亢龍有悔-何謂也-子曰-貴而無位-高而無民-賢人在下而無輔-是以動而有悔也。" tabindex="-1">上九曰“亢龍有悔”，何謂也?子曰：貴而無位，高而無民，賢人在下而無輔，是以動而有悔也。 <a class="header-anchor" href="#上九曰-亢龍有悔-何謂也-子曰-貴而無位-高而無民-賢人在下而無輔-是以動而有悔也。" aria-label="Permalink to “上九曰“亢龍有悔”，何謂也?子曰：貴而無位，高而無民，賢人在下而無輔，是以動而有悔也。”">​</a></h3><p>六，龍之首，故曰高貴。非君非臣，故曰無位。純陽無陰，故曰無民。五居九五之位，又有快睹之民。九四以下，龍德之賢，皆相從九五以輔相矣。是以上九非不貴也，貴宜乎有位，而無位;非不高也，高宜乎有民，而無民;非不有賢人也，賢人宜輔而莫為之輔。無位無民無輔，則離群孤立，如是而動，其誰我與?有悔必矣。此第二節申象傳之意。</p><h3 id="潛龍勿用-下也。" tabindex="-1">潛龍勿用，下也。 <a class="header-anchor" href="#潛龍勿用-下也。" aria-label="Permalink to “潛龍勿用，下也。”">​</a></h3><p>言在下位也。</p><h3 id="見龍在田-時舍也。" tabindex="-1">見龍在田，時舍也。 <a class="header-anchor" href="#見龍在田-時舍也。" aria-label="Permalink to “見龍在田，時舍也。”">​</a></h3><p>舍，止息也，出潛離隱，而止息于田也。</p><h3 id="終日乾乾-行事也。" tabindex="-1">終日乾乾，行事也。 <a class="header-anchor" href="#終日乾乾-行事也。" aria-label="Permalink to “終日乾乾，行事也。”">​</a></h3><p>非空憂惕，乃行所當行之事也，即進德修業也。</p><h3 id="或躍在淵-自試也。" tabindex="-1">或躍在淵，自試也。 <a class="header-anchor" href="#或躍在淵-自試也。" aria-label="Permalink to “或躍在淵，自試也。”">​</a></h3><p>試可乃已之試，非試其德，試其時也，非自試則必妄動矣。</p><h3 id="飛龍在天-上治也。" tabindex="-1">飛龍在天，上治也。 <a class="header-anchor" href="#飛龍在天-上治也。" aria-label="Permalink to “飛龍在天，上治也。”">​</a></h3><p>居上以治下。</p><h3 id="亢龍有悔-窮之災也。" tabindex="-1">亢龍有悔，窮之災也。 <a class="header-anchor" href="#亢龍有悔-窮之災也。" aria-label="Permalink to “亢龍有悔，窮之災也。”">​</a></h3><p>窮者亢，災者悔。</p><h3 id="乾元用九-天下治也。" tabindex="-1">乾元用九，天下治也。 <a class="header-anchor" href="#乾元用九-天下治也。" aria-label="Permalink to “乾元用九，天下治也。”">​</a></h3><p>用九見群龍無首吉，此周公教佔者當如此也。孔子此則專以人君言元者，仁也，即體仁以長人也。言人君體幹之元，用幹之九至誠惻怛之愛，常流行於剛果嚴肅之中，則張弛有則，寬猛得宜，不剛不柔，敷政優優，而天下治矣。此第三節再申前意。</p><h3 id="潛龍勿用-陽氣潛藏。" tabindex="-1">潛龍勿用，陽氣潛藏。 <a class="header-anchor" href="#潛龍勿用-陽氣潛藏。" aria-label="Permalink to “潛龍勿用，陽氣潛藏。”">​</a></h3><p>陽在下也，以爻言;潛龍勿用，下也，以位言。此則以氣言，言陽氣潛藏，正陰氣極盛之時，天地閉，賢人隱，所以勿用。此以下，又聖人歌詠乾道之意。觀其句，皆四字，有音韻，可知矣。</p><h3 id="見龍在田-天下文明。" tabindex="-1">見龍在田，天下文明。 <a class="header-anchor" href="#見龍在田-天下文明。" aria-label="Permalink to “見龍在田，天下文明。”">​</a></h3><p>雖在下位，然天下已被其德化，而成文明之俗矣，因此爻變離，故以文明言之。</p><h3 id="終日乾乾-與時偕行。" tabindex="-1">終日乾乾，與時偕行。 <a class="header-anchor" href="#終日乾乾-與時偕行。" aria-label="Permalink to “終日乾乾，與時偕行。”">​</a></h3><p>天之健，終日不息，九三之進修，亦與之偕行而不息，故曰與時偕行。</p><h3 id="或躍在淵-乾道乃革。" tabindex="-1">或躍在淵，乾道乃革。 <a class="header-anchor" href="#或躍在淵-乾道乃革。" aria-label="Permalink to “或躍在淵，乾道乃革。”">​</a></h3><p>革者，離下內卦之位，升上外卦之位也。</p><h3 id="飛龍在天-乃位乎天德。" tabindex="-1">飛龍在天，乃位乎天德。 <a class="header-anchor" href="#飛龍在天-乃位乎天德。" aria-label="Permalink to “飛龍在天，乃位乎天德。”">​</a></h3><p>天德即天位，有是天德，而居是天位，故曰乃位乎天德。若無德以居之者，可謂之天位，不可謂之天德之位也，惟聖人在天子之位，斯可言乃為乎天德也。</p><h3 id="亢龍有悔-與時偕極。" tabindex="-1">亢龍有悔，與時偕極。 <a class="header-anchor" href="#亢龍有悔-與時偕極。" aria-label="Permalink to “亢龍有悔，與時偕極。”">​</a></h3><p>當亢極，而我不能變通，亦與時運俱極，所以有悔。</p><h3 id="乾元用九-乃見天則。" tabindex="-1">乾元用九，乃見天則。 <a class="header-anchor" href="#乾元用九-乃見天則。" aria-label="Permalink to “乾元用九，乃見天則。”">​</a></h3><p>龍之為物，春分而升於天，秋分而蟄於淵。曰亢龍者，言秋分亢舉於上，而不能蟄也。以春夏秋冬配四德，元者春也，利者秋也，亢龍在此，秋之時矣。天之為天，不過生殺而已。春既生矣，至秋又殺;秋既殺矣，至春又生，此天道一定，自然之法則也。今為人君者，體春生之元，而用之於秋殺之亢，則是陰慘之後繼之以陽舒，肅殺之餘繼之以生育，一張一弛，一剛一柔，不惟天下可治，而天道之法，則亦於此而見矣，故曰乃見天則。此四節又申前意。</p><h3 id="乾元者-始而亨者也。利貞者-性情也。乾始能以美利利天下-不言所利-大矣哉。" tabindex="-1">乾元者，始而亨者也。利貞者，性情也。乾始能以美利利天下，不言所利，大矣哉。 <a class="header-anchor" href="#乾元者-始而亨者也。利貞者-性情也。乾始能以美利利天下-不言所利-大矣哉。" aria-label="Permalink to “乾元者，始而亨者也。利貞者，性情也。乾始能以美利利天下，不言所利，大矣哉。”">​</a></h3><p>始而亨者，言物方資始之時，已亨通矣。蓋出乎震，則必齊乎巽，見乎離，勢之必然也。若不亨通，則生意必息，品物不能流形矣。是始者元也，亨之者亦元也。性者百物具足之理，情者百物出入之機，春作夏長，百物皆有性情，非必利貞而後見。但此時生意未足，實理未完，百物尚共同一性情，至秋冬則百穀草木，各正性命，保合太和，一物各具一性情，是收斂歸藏，乃見性情之的確。故利貞者，即乾元之性情也，則利貞之未始不為元也。乾始者，即乾元者始而亨之始也。以美利利天下者，元能始物，能始庶物生成，無物不嘉美，亦無物不利賴也。不言所利者，自成其形，自成其性，泯機緘於不露，莫知其所以然也。大哉，贊乾元也。</p><p>孔子於文言，既分元亨利貞為四德矣，此又合而為一也。言幹之元者，始而即亨者也;利貞者，則元之性情耳。然何以知其元始即亨，利貞即元之性情也。惟自其乾元之所能者，則可見矣。蓋百物生於春，非亨利貞之所能也，惟元為生物之始。以美利利天下者，則乾元之能也。夫以美利利天下，其所能之德業，亦盛大矣。使造化可以言焉，則曰此某之美利也，庶乎可以各歸功於四德矣。今不言所利，人不得而測之，既不可得而測，則是四德渾然一理，不可分而言也。元本為四德之長，故謂亨，乃元之始亨可也。謂利貞，乃元之性情可也。所以謂乾元始而亨，利貞性情者，以此乾元之道，不其大哉。四德本一理，孔子贊易，或分而言之以盡其用，或合而言之以著其體，其實一理而已，所以可分可合也。</p><h3 id="大哉幹乎-剛健中正-純粹精也。六爻發揮-旁通情也。時乘六龍-以御天也。雲行雨施-天下平也。" tabindex="-1">大哉幹乎，剛健中正，純粹精也。六爻發揮，旁通情也。時乘六龍，以御天也。雲行雨施，天下平也。 <a class="header-anchor" href="#大哉幹乎-剛健中正-純粹精也。六爻發揮-旁通情也。時乘六龍-以御天也。雲行雨施-天下平也。" aria-label="Permalink to “大哉幹乎，剛健中正，純粹精也。六爻發揮，旁通情也。時乘六龍，以御天也。雲行雨施，天下平也。”">​</a></h3><p>剛以體言，健以性言，中者無過不及也，正者不偏也，此四者幹之德也。純者純陽而不雜以陰也，粹者不雜而良美也，精者不雜之極至也，總言乾德剛健中正之至極。所謂純粹精者，非出於剛健中正之外也，但乾德之妙，非一言所能盡，故於剛健中正之外，復以純粹精贊之。情者事物至賾至動之情也，發揮者每一畫有一爻辭以發揮之也，旁通者曲盡也，如初之潛以至上之亢，凡事有萬殊，物有萬類，時有萬變，皆該括曲盡其情而無遺也。前品物流形，乃幹之雲行雨施，此言云行雨施，乃聖人乘六龍而御天之功德澤流行敷布，所以天下平也。</p><p>言乾道剛健中正，純粹以精。乾道固大矣，惟聖人立六爻以通乎幹之情，乘六龍以行乎幹之道。雲行雨施，以沛乎幹之澤，以至天下太平，則乾道之大不在幹而在聖人矣。此第五節復申首章之意。</p><h3 id="君子以成德為行-日可見之行也。潛之為言也-隱而未見-行而未成-是以君子弗用也。" tabindex="-1">君子以成德為行，日可見之行也。潛之為言也，隱而未見，行而未成，是以君子弗用也。 <a class="header-anchor" href="#君子以成德為行-日可見之行也。潛之為言也-隱而未見-行而未成-是以君子弗用也。" aria-label="Permalink to “君子以成德為行，日可見之行也。潛之為言也，隱而未見，行而未成，是以君子弗用也。”">​</a></h3><p>德者行之本，行者德之用，蓋有有其德而不見諸行者，未有有其行而不本諸德者，故曰君子以成德為行。成德者，已成之德也。日可見者，猶言指日可待之意。此二句泛論其理也。潛者周公爻辭也。未見者，天地閉，賢人隱，厄於潛之機會而未見也。未成者，因其厄而事業未成就也，如伊尹耕於有莘之野是也。</p><p>君子以已成之德，舉而措之於行，則其事業之所就，指日可見矣。初九其德已成，則日可見之行也，而佔者乃曰勿用，何也?蓋聖人出世，必有德有時。人之所能者德，所不能者時。今初九雖德已成，然時當乎潛也。潛之為言也，隱而未見也。惟其隱而未見，故行而未成，時位厄之也。是以佔者之君子，亦當如之而勿用也。</p><h3 id="君子學以聚之-問以辨之-寬以居之-仁以行之。易曰-見龍在田-利見大人-君德也。" tabindex="-1">君子學以聚之，問以辨之，寬以居之，仁以行之。易曰“見龍在田，利見大人”，君德也。 <a class="header-anchor" href="#君子學以聚之-問以辨之-寬以居之-仁以行之。易曰-見龍在田-利見大人-君德也。" aria-label="Permalink to “君子學以聚之，問以辨之，寬以居之，仁以行之。易曰“見龍在田，利見大人”，君德也。”">​</a></h3><p>之者正中之理也。龍德正中，雖以爻言，然聖人之德，不過此至正大中而已。蓋乾道剛健中正，民受天地之中以生，惟中庸不可能，苟非學聚問辨，有此致知功夫，寬居仁行，有此力行功，夫安能體此龍德之正中乎。聚者多聞多見以我會聚，此正中之理也。辨者講學也，親師取友，辨其理之精粗本末，得失是非，擇其正中之善者而從之，即講學以耨之也。寬者優遊厭飫，勿忘勿助，俾所聚所辨，此理之畜於我者，融會貫通，渣滓渾化，無強探力索，凌節慾速之患也。蓋寬字以久遠言，有從容不迫之意，非專指包含也。居者守也據也，仁以行之者，無適而莫非天理正中之公，而無一毫意必固我之私也。蓋辨者辨其所聚，居者居其所辨，行者行其所居，故必寬以居之，而後方可仁以行之。若學聚問辨之餘，涵養未久，粗心浮氣，而驟欲見之於實踐，則居之不安，資之不深，安能左右逢原，而大公以順應哉。此為學一定之序也，有是四者，宜乎正中之德，博而化矣。曰君德者，即前九二之君德也。</p><h3 id="九三重剛而不中-上不在天-下不在田-故乾乾。因其時而惕-雖危無咎矣。" tabindex="-1">九三重剛而不中，上不在天，下不在田，故乾乾。因其時而惕，雖危無咎矣。 <a class="header-anchor" href="#九三重剛而不中-上不在天-下不在田-故乾乾。因其時而惕-雖危無咎矣。" aria-label="Permalink to “九三重剛而不中，上不在天，下不在田，故乾乾。因其時而惕，雖危無咎矣。”">​</a></h3><p>三居下卦之上，四居上卦之下，交接處，以剛居剛，故曰重剛，非陽爻居陽位也。所以九四居陰位者，亦曰重剛。位非二五，故曰不中。即下文上不在天，下不在田也。九三以時言，九四以位言，故曰乾乾，因其時。</p><p>九三重剛不中，上不在天，下不在田，宜有咎矣，而乃無咎，何哉?蓋既重剛又不中，剛之極矣。以時論之，蓋危懼之時也。故九三因其時而兢惕不已，則德日進，業日修，所以雖處危地，亦無咎矣。</p><h3 id="九四重剛而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故無咎。" tabindex="-1">九四重剛而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故無咎。 <a class="header-anchor" href="#九四重剛而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故無咎。" aria-label="Permalink to “九四重剛而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故無咎。”">​</a></h3><p>在人謂三也。四三雖皆人位，然四則居人之上，而近君矣。非三之不近君，故曰不在人。重剛不中之中，二五之中也。中不在人之中，六爻中間之中也。</p><p>九四重剛不中，上不在天，下不在田，中不在人，宜有咎矣，而乃無咎，何哉?蓋九四之位不在天，不在田，雖與九三同，而人位則不如九三之居下卦也，所居之位獨近九五，蓋或之之位也，故或之。或之者疑之也，惟其疑，必審時而進矣，所以無咎也。</p><h3 id="夫大人者-與天地合其德-與日月合其明-與四時合其序-與鬼神合其吉凶-先天而天弗違-後天而奉天時-天且弗違-而況於人乎-況於鬼神乎。-夫音扶" tabindex="-1">夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，先天而天弗違，後天而奉天時，天且弗違，而況於人乎，況於鬼神乎。(夫音扶) <a class="header-anchor" href="#夫大人者-與天地合其德-與日月合其明-與四時合其序-與鬼神合其吉凶-先天而天弗違-後天而奉天時-天且弗違-而況於人乎-況於鬼神乎。-夫音扶" aria-label="Permalink to “夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，先天而天弗違，後天而奉天時，天且弗違，而況於人乎，況於鬼神乎。(夫音扶)”">​</a></h3><p>合德以下，總言大人所具之德，皆天理之公，而無一毫人慾之私。若少有一毫人慾之私，即不合矣。天地者造化之主，日月者造化之精，四時者造化之功，鬼神者造化之靈，覆哉無私之謂德，照臨無私之謂明，生息無私之謂序，禍福無私之謂吉凶。合序者如賞以春夏，罰以秋冬之類也。合吉凶者，福善禍淫也。先天不違如禮，雖先王所未有，以義起之，凡制耒耜、作書契之類。雖天下之所未為，而吾意之所為，默與道契，天亦不違乎我，是天合大人也。奉天時者，奉天理也。後天奉天時謂如天敘有典，而我惇之，天秩有禮，而我庸之類，雖天之所已為，我知理之如是，奉而行之，而我亦不能違乎天，是大人合天也。蓋以理為主，天即我，我即天，故無後先彼此之可言矣。且不違於大人，而況於人。乃得天地之理以生鬼神，不過天地之功用，雖欲違乎大人，自不能違乎天矣。幹之九五，以剛健中正之德，與此大人相合，所以宜利見之，以其同德相應也。</p><h3 id="亢之為言也-知進而不知退-知存而不知亡-知得而不知喪-其惟聖人乎。知進退存亡而不失其正者-其唯聖人乎。" tabindex="-1">亢之為言也，知進而不知退，知存而不知亡，知得而不知喪，其惟聖人乎。知進退存亡而不失其正者，其唯聖人乎。 <a class="header-anchor" href="#亢之為言也-知進而不知退-知存而不知亡-知得而不知喪-其惟聖人乎。知進退存亡而不失其正者-其唯聖人乎。" aria-label="Permalink to “亢之為言也，知進而不知退，知存而不知亡，知得而不知喪，其惟聖人乎。知進退存亡而不失其正者，其唯聖人乎。”">​</a></h3><p>進退者身，存亡者位，得喪者物。消長之理，知之既明，不失其正，處之又當，故惟聖人能之。再言其唯聖人，始若設問，而卒自應之，見非聖人不能也。初九隱而未見二句，釋一潛字。而言君子者再，蓋必君子而後能安於潛也。上九亢之為言三句，釋一亢字。而言聖人者再，蓋必聖人而後能不至於亢也。此第六節復申前數節未盡之意。</p>',120)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
